const GITHUB_TOKEN = $env.GITHUB_TOKEN;
const REPO = 'luizinhotec/advocacia-ai-vault';
const PROJETO_ID = 3;

async function fetchGitHub(url) {
  const res = await fetch(url, {
    headers: {
      Authorization: `Bearer ${GITHUB_TOKEN}`,
      Accept: 'application/vnd.github+json'
    }
  });
  return res.json();
}

const [issues, prs] = await Promise.all([
  fetchGitHub(`https://api.github.com/repos/${REPO}/issues?state=open&per_page=50`),
  fetchGitHub(`https://api.github.com/repos/${REPO}/pulls?state=open&per_page=50`)
]);

const tarefas = [];

if (Array.isArray(issues)) {
  for (const issue of issues) {
    if (issue.pull_request) continue;
    tarefas.push({
      projeto_id: PROJETO_ID,
      titulo: `[ISSUE #${issue.number}] ${issue.title}`,
      descricao: (issue.body || '').substring(0, 500),
      responsavel: issue.assignee?.login || 'nao-atribuido',
      status: 'BACKLOG'
    });
  }
}

if (Array.isArray(prs)) {
  for (const pr of prs) {
    tarefas.push({
      projeto_id: PROJETO_ID,
      titulo: `[PR #${pr.number}] ${pr.title}`,
      descricao: (pr.body || '').substring(0, 500),
      responsavel: pr.user?.login || 'nao-atribuido',
      status: 'ANÁLISE'
    });
  }
}

if (tarefas.length === 0) {
  return [{ json: { skip: true, mensagem: 'Nenhuma issue ou PR aberta' } }];
}

return tarefas.map(t => ({ json: t }));

